package com.tracker.service; import com.tracker.entity.User; import com.tracker.exception.ApiException; import com.tracker.repository.UserRepository; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; @Service public class AccessService {private final UserRepository users; public AccessService(UserRepository u){users=u;} public User current(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow(()->new ApiException("User not found",HttpStatus.NOT_FOUND));} public User byId(Long id){return users.findById(id).orElseThrow(()->new ApiException("User not found",HttpStatus.NOT_FOUND));} public User save(User u){return users.save(u);} public void own(Long id,Authentication a){if(!current(a).getId().equals(id)&&!a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN")))throw new ApiException("You do not have access to this record",HttpStatus.FORBIDDEN);}}
